mapper.update:
UPDATE wms_stock SET qty = qty + #{qty}, update_time = NOW()
WHERE warehouse_id = #{warehouseId} AND location_id = #{locationId}
  AND material_id = #{materialId} AND batch_no = #{batchNo}

UPDATE wms_stock SET qty = qty - #{qty}, update_time = NOW()
WHERE warehouse_id = #{warehouseId} AND location_id = #{locationId}
  AND material_id = #{materialId} AND batch_no = #{batchNo}
  AND qty - frozen_qty >= #{qty}

UPDATE wms_stock SET frozen_qty = frozen_qty + #{qty}, update_time = NOW()
WHERE warehouse_id = #{warehouseId} AND location_id = #{locationId}
  AND material_id = #{materialId} AND batch_no = #{batchNo}
  AND qty - frozen_qty >= #{qty}

UPDATE wms_stock SET frozen_qty = frozen_qty - #{qty}, update_time = NOW()
WHERE warehouse_id = #{warehouseId} AND location_id = #{locationId}
  AND material_id = #{materialId} AND batch_no = #{batchNo}
  AND frozen_qty >= #{qty}

